trigger.description:
Service count increased on the ESB.

Service count: {ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.count,#2} -> {ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.count}

Previous service list:
{ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.list.sorted,#2}

Current service list:
{ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.list.sorted}

Compare both lists to identify the new service(s).

Service count decreased on the ESB.

Service count: {ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.count,#2} -> {ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.count}

Previous service list:
{ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.list.sorted,#2}

Current service list:
{ITEM.VALUE:/WSO2 ESB Service Monitoring/wso2.esb.services.list.sorted}

Compare both lists to identify which service(s) were removed and review the ESB configuration.

parameters.parameter:
// Calculate difference between current and previous service lists
// Returns JSON with added and removed services

// Current list (comma separated)
var current = value;

// Try to get previous value from history - if not available, return empty
try {
    // For first run, there's no history
    var result = {
        added: [],
        removed: [],
        status: "first_run"
    };
    return JSON.stringify(result);
} catch (error) {
    var result = {
        added: [],
        removed: [],
        status: "error",
        error: error.toString()
    };
    return JSON.stringify(result);
}

item.params:
var url = 'https://{$WSO2.HOST}:{$WSO2.PORT}/services/ServiceAdmin';
var username = '{$WSO2.SOAP.USERNAME}';
var password = '{$WSO2.SOAP.PASSWORD}';

var services = [];
var request = new HttpRequest();
request.addHeader('Content-Type: text/xml; charset=utf-8');
request.addHeader('SOAPAction: urn:listServices');
var auth = btoa(username + ':' + password);
request.addHeader('Authorization: Basic ' + auth);

try {
    var envelope = '<?xml version="1.0"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:xsd="http://org.apache.axis2/xsd"><soapenv:Body><xsd:listServices><xsd:pageNumber>0</xsd:pageNumber></xsd:listServices></soapenv:Body></soapenv:Envelope>';
    var response = request.post(url, envelope);
    var statusCode = request.getStatus();

    if (statusCode !== 200) {
        return JSON.stringify([{'ERROR': 'HTTP Error ' + statusCode}]);
    }

    if (response.indexOf('faultstring') !== -1) {
        var faultMatch = response.match(/faultstring>([^<]+)</);
        var faultMsg = faultMatch ? faultMatch[1] : 'Unknown SOAP Fault';
        return JSON.stringify([{'ERROR': 'SOAP Fault: ' + faultMsg}]);
    }

    var pagesMatch = response.match(/numberOfPages>(\d+)</);
    var totalPages = pagesMatch ? parseInt(pagesMatch[1]) : 1;

    for (var page = 0; page < totalPages; page++) {
        if (page > 0) {
            envelope = '<?xml version="1.0"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:xsd="http://org.apache.axis2/xsd"><soapenv:Body><xsd:listServices><xsd:pageNumber>' + page + '</xsd:pageNumber></xsd:listServices></soapenv:Body></soapenv:Envelope>';
            response = request.post(url, envelope);
        }

        // Split by services tag - namespace independent
        var parts = response.split(':services');

        for (var s = 1; s < parts.length; s++) {
            var block = parts[s];

            var nameMatch = block.match(/:name>([^<]+)</);
            var typeMatch = block.match(/:serviceType>([^<]+)</);
            var wsdlMatch = block.match(/:wsdlURLs>([^<]+)</);

            if (nameMatch && typeMatch) {
                var serviceName = nameMatch[1];
                var serviceType = typeMatch[1];
                var wsdlUrl = wsdlMatch ? wsdlMatch[1] : '';

                var exists = false;
                for (var j = 0; j < services.length; j++) {
                    if (services[j]['SERVICE_NAME'] === serviceName) {
                        exists = true;
                        break;
                    }
                }

                if (!exists) {
                    services.push({'SERVICE_NAME': serviceName, 'SERVICE_TYPE': serviceType, 'WSDL_URL': wsdlUrl});
                }
            }
        }
    }

    if (services.length === 0) {
        return JSON.stringify([{'ERROR': 'No services found', 'RESPONSE': response.substring(0, 200)}]);
    }

    return JSON.stringify(services);

} catch (error) {
    return JSON.stringify([{'ERROR': error.toString()}]);
}

var url = 'https://{$WSO2.HOST}:{$WSO2.PORT}/services/ServiceAdmin';
var username = '{$WSO2.SOAP.USERNAME}';
var password = '{$WSO2.SOAP.PASSWORD}';

var inactiveServices = [];
var request = new HttpRequest();
request.addHeader('Content-Type: text/xml; charset=utf-8');
request.addHeader('SOAPAction: urn:listServices');
var auth = btoa(username + ':' + password);
request.addHeader('Authorization: Basic ' + auth);

try {
    var envelope = '<?xml version="1.0"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:xsd="http://org.apache.axis2/xsd"><soapenv:Body><xsd:listServices><xsd:pageNumber>0</xsd:pageNumber></xsd:listServices></soapenv:Body></soapenv:Envelope>';
    var response = request.post(url, envelope);
    var statusCode = request.getStatus();

    if (statusCode !== 200) {
        return 'Error: HTTP ' + statusCode;
    }

    if (response.indexOf('faultstring') !== -1) {
        var faultMatch = response.match(/faultstring>([^<]+)</);
        var faultMsg = faultMatch ? faultMatch[1] : 'SOAP Fault';
        return 'Error: ' + faultMsg;
    }

    var pagesMatch = response.match(/numberOfPages>(\d+)</);
    var totalPages = pagesMatch ? parseInt(pagesMatch[1]) : 1;

    for (var page = 0; page < totalPages; page++) {
        if (page > 0) {
            envelope = '<?xml version="1.0"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:xsd="http://org.apache.axis2/xsd"><soapenv:Body><xsd:listServices><xsd:pageNumber>' + page + '</xsd:pageNumber></xsd:listServices></soapenv:Body></soapenv:Envelope>';
            response = request.post(url, envelope);
        }

        var parts = response.split(':services');

        for (var s = 1; s < parts.length; s++) {
            var block = parts[s];

            var nameMatch = block.match(/:name>([^<]+)</);
            var activeMatch = block.match(/:active>([^<]+)</);

            if (nameMatch && activeMatch) {
                var serviceName = nameMatch[1];
                var isActive = activeMatch[1];

                if (isActive === 'false') {
                    var exists = false;
                    for (var j = 0; j < inactiveServices.length; j++) {
                        if (inactiveServices[j] === serviceName) {
                            exists = true;
                            break;
                        }
                    }

                    if (!exists) {
                        inactiveServices.push(serviceName);
                    }
                }
            }
        }
    }

    if (inactiveServices.length > 0) {
        return inactiveServices.join(', ');
    } else {
        return 'All services active';
    }

} catch (error) {
    return 'Error: ' + error.toString();
}

