return names.join(',');

item.params:
var url = 'https://{$WSO2.HOST}:{$WSO2.PORT}/services/StatisticsAdmin';
var username = '{$WSO2.SOAP.USERNAME}';
var password = '{$WSO2.SOAP.PASSWORD}';

try {
    var request = new HttpRequest();
    request.addHeader('Content-Type: text/xml; charset=utf-8');
    request.addHeader('SOAPAction: urn:getSystemStatistics');
    var auth = btoa(username + ':' + password);
    request.addHeader('Authorization: Basic ' + auth);

    var envelope = '<?xml version="1.0"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:xsd="http://org.apache.axis2/xsd"><soapenv:Body><xsd:getSystemStatistics/></soapenv:Body></soapenv:Envelope>';

    var response = request.post(url, envelope);

    if (request.getStatus() !== 200) {
        throw 'HTTP Error ' + request.getStatus();
    }

    var returnBlock = response.split(':return')[1];
    if (!returnBlock) {
        throw 'No return block found in XML response';
    }

    var extractField = function(xml, fieldName) {
        var pattern = ':' + fieldName + '>([^<]+)<';
        var match = xml.match(new RegExp(pattern));
        return match ? match[1] : null;
    };

    var totalFaults = extractField(returnBlock, 'totalFaultCount');
    var totalRequests = extractField(returnBlock, 'totalRequestCount');
    var totalResponses = extractField(returnBlock, 'totalResponseCount');

    var currentTime = Math.floor(Date.now() / 1000);

    var stats = {
        totalRequestCount: totalRequests ? Math.floor(Number(totalRequests)) : 0,
        totalFaultCount: totalFaults ? Math.floor(Number(totalFaults)) : 0,
        totalResponseCount: totalResponses ? Math.floor(Number(totalResponses)) : 0,
        timestamp: currentTime
    };

    return JSON.stringify(stats);

} catch (error) {
    return JSON.stringify({
        totalRequestCount: 0,
        totalFaultCount: 0,
        totalResponseCount: 0,
        timestamp: 0,
        error: error.toString()
    });
}

trigger.description:
Error rate on the WSO2 ESB is above the configured threshold.

Error rate: {ITEM.LASTVALUE}%
Total faults: {ITEM.LASTVALUE:/WSO2 ESB Service Monitoring/wso2.esb.system.faultcount.raw}
Total requests: {ITEM.LASTVALUE:/WSO2 ESB Service Monitoring/wso2.esb.system.requestcount.raw}

Inspect service logs and the per-service "Service [SERVICE_NAME]: Fault Delta" items to identify which service is generating new faults.

item.params:
var url = 'https://{$WSO2.HOST}:{$WSO2.PORT}/services/StatisticsAdmin';
var username = '{$WSO2.SOAP.USERNAME}';
var password = '{$WSO2.SOAP.PASSWORD}';

try {
    var request = new HttpRequest();
    request.addHeader('Content-Type: text/xml; charset=utf-8');
    request.addHeader('SOAPAction: urn:getSystemStatistics');
    var auth = btoa(username + ':' + password);
    request.addHeader('Authorization: Basic ' + auth);

    var envelope = '<?xml version="1.0"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:xsd="http://org.apache.axis2/xsd"><soapenv:Body><xsd:getSystemStatistics/></soapenv:Body></soapenv:Envelope>';

    var response = request.post(url, envelope);

    if (request.getStatus() !== 200) {
        throw 'HTTP Error ' + request.getStatus();
    }

    var returnBlock = response.split(':return')[1];
    if (!returnBlock) {
        throw 'No return block found in XML response';
    }

    var extractField = function(xml, fieldName) {
        var pattern = ':' + fieldName + '>([^<]+)<';
        var match = xml.match(new RegExp(pattern));
        return match ? match[1] : null;
    };

    var extractNestedValue = function(xml, fieldName) {
        var pattern = ':' + fieldName + '[^>]*>[\\s\\S]*?:value>([^<]+)<';
        var match = xml.match(new RegExp(pattern));
        return match ? match[1] : null;
    };

    var serverName = extractField(returnBlock, 'serverName');
    var totalFaults = extractField(returnBlock, 'totalFaultCount');
    var totalRequests = extractField(returnBlock, 'totalRequestCount');
    var totalResponses = extractField(returnBlock, 'totalResponseCount');
    var avgResp = extractField(returnBlock, 'avgResponseTime');
    var minResp = extractField(returnBlock, 'minResponseTime');
    var maxResp = extractField(returnBlock, 'maxResponseTime');
    var startTime = extractField(returnBlock, 'serverStartTime');
    var upTime = extractField(returnBlock, 'systemUpTime');

    var totalMem = extractNestedValue(returnBlock, 'totalMemory');
    var usedMem = extractNestedValue(returnBlock, 'usedMemory');

    var stats = {
        serverName: serverName || 'Unknown',
        totalFaultCount: totalFaults ? Math.floor(Number(totalFaults)) : 0,
        totalRequestCount: totalRequests ? Math.floor(Number(totalRequests)) : 0,
        totalResponseCount: totalResponses ? Math.floor(Number(totalResponses)) : 0,
        avgResponseTime: avgResp ? Math.round(Number(avgResp) * 100) / 100 : 0,
        minResponseTime: minResp ? Math.round(Number(minResp) * 100) / 100 : 0,
        maxResponseTime: maxResp ? Math.round(Number(maxResp) * 100) / 100 : 0,
        totalMemory: totalMem ? Math.round(Number(totalMem) * 100) / 100 : 0,
        usedMemory: usedMem ? Math.round(Number(usedMem) * 100) / 100 : 0,
        serverStartTime: startTime || '',
        systemUpTime: upTime || ''
    };

    return JSON.stringify(stats);

} catch (error) {
    return JSON.stringify({error: error.toString()});
}

item_prototype.params:
// Error Rate calculation with error handling
var serviceName = '{#SERVICE.NAME}';

try {
    // Get faults and requests values
    var faultsKey = 'wso2.esb.service.stat.faults[' + serviceName + ']';
    var requestsKey = 'wso2.esb.service.stat.requests[' + serviceName + ']';

    var faults = Zabbix.getItemValue(faultsKey);
    var requests = Zabbix.getItemValue(requestsKey);

    // Check if values are valid
    if (faults === null || requests === null) {
        Zabbix.log(4, 'Error Rate: No data available for ' + serviceName);
        return 0;
    }

    // Convert to numbers
    faults = parseFloat(faults);
    requests = parseFloat(requests);

    // Avoid division by zero
    if (requests === 0) {
        return 0;
    }

    // Calculate error rate
    var errorRate = (faults / requests) * 100;

    return errorRate;

} catch (error) {
    Zabbix.log(4, 'Error Rate calculation failed for ' + serviceName + ': ' + error);
    return 0;
}
